      returning id into new_spec_id;
    update report_types set active_spec_id = new_spec_id where id = rt_id;
    raise notice '[0007] msc spec v1 inserida e ativada (id=%)', new_spec_id;
  else
    raise notice '[0007] msc ja tem spec v%, pulando', max_ver;
  end if;
end $$;
